import type * as React from "react"

/** One link of the CRM side menu (Figma `item-sidemenu-menu-tree-states`, 44px). */
export type SideMenuItemData = {
  id: string
  label: string
  href: string
  icon?: React.ComponentType<React.ComponentProps<"svg">>
  /** Counter or badge after the label, e.g. <Badge size="sm">3</Badge>. */
  badge?: React.ReactNode
}

/** A group with an optional uppercase header (Figma `listMenu` + `header`, 36px). */
export type SideMenuSectionData = {
  id: string
  title?: string
  items: SideMenuItemData[]
  /** Header gets a chevron button that hides/shows the items. */
  collapsible?: boolean
  /** Extra control on the right of the header, e.g. a "+" icon button. */
  action?: React.ReactNode
}

export type SideMenuLinkProps = {
  item: SideMenuItemData
  className: string
  "aria-current"?: "page"
  children: React.ReactNode
}

/** Renders the link element; pass the router's Link here (default: a plain <a href>). */
export type RenderSideMenuLink = (props: SideMenuLinkProps) => React.ReactNode

import { cn } from "@/registry/mbank/lib/utils"
import type { RenderSideMenuLink, SideMenuItemData, SideMenuLinkProps } from "./side-menu-types"

const anchor: RenderSideMenuLink = ({ item, ...props }: SideMenuLinkProps) => (
  <a href={item.href} {...props} />
)

type SideMenuItemProps = {
  item: SideMenuItemData
  active?: boolean
  /** Icon-only rail: the label stays for screen readers. */
  collapsed?: boolean
  renderLink?: RenderSideMenuLink
}

/** Figma `item-sidemenu-menu-tree-states`: 44px, icon 20, active = white surface. */
export function SideMenuItem({ item, active = false, collapsed = false, renderLink = anchor }: SideMenuItemProps) {
  const Icon = item.icon
  const className = cn(
    "flex h-11 items-center gap-3 rounded-md px-3 text-md text-foreground transition-colors outline-none",
    "hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/30 aria-[current=page]:bg-background",
    collapsed && "justify-center px-0",
  )
  return (
    <li data-slot="side-menu-item">
      {renderLink({
        item,
        className,
        "aria-current": active ? "page" : undefined,
        children: (
          <>
            {Icon && <Icon className="size-5 shrink-0" />}
            <span className={cn("min-w-0 flex-1 truncate", collapsed && "sr-only")}>{item.label}</span>
            {!collapsed && item.badge}
          </>
        ),
      })}
    </li>
  )
}

import { useId, useState } from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { ChevronDownIcon } from "@/registry/mbank/ui/icons"
import { SideMenuItem } from "./SideMenuItem"
import type { RenderSideMenuLink, SideMenuSectionData } from "./side-menu-types"

type SideMenuSectionProps = {
  section: SideMenuSectionData
  activeId?: string
  collapsed?: boolean
  renderLink?: RenderSideMenuLink
}

/** Figma `listMenu`: uppercase 36px header (chevron + title + action) and 44px items. */
export function SideMenuSection({ section, activeId, collapsed = false, renderLink }: SideMenuSectionProps) {
  const [open, setOpen] = useState(true)
  const listId = useId()
  const showHeader = Boolean(section.title) && !collapsed
  const headerText = "text-caption font-medium uppercase text-muted-foreground"

  return (
    <div data-slot="side-menu-section" className="group/section px-3">
      <div className="border-b border-border py-2 group-last/section:border-b-0">
        {showHeader && (
          <div className="flex h-9 items-center justify-between gap-2 pr-1">
            {section.collapsible ? (
              <button
                type="button"
                aria-expanded={open}
                aria-controls={listId}
                onClick={() => setOpen((value) => !value)}
                className={cn(
                  headerText,
                  "flex h-9 items-center gap-3 rounded-sm px-3 outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/30",
                )}
              >
                <ChevronDownIcon className={cn("size-5 transition-transform", !open && "-rotate-90")} />
                {section.title}
              </button>
            ) : (
              <span className={cn(headerText, "px-3")}>{section.title}</span>
            )}
            {section.action}
          </div>
        )}
        <ul
          id={listId}
          aria-label={section.title}
          hidden={!open && !collapsed}
          className="flex flex-col"
        >
          {section.items.map((item) => (
            <SideMenuItem
              key={item.id}
              item={item}
              active={item.id === activeId}
              collapsed={collapsed}
              renderLink={renderLink}
            />
          ))}
        </ul>
      </div>
    </div>
  )
}

import { useId } from "react"
import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"

/**
 * Mbank logo mark (Figma `logoCont` / `Logo`, 36px): green → teal tile, yellow left stroke, white "1".
 * Colours are the fixed product tokens (logos only). TODO: replace the paths with the SVG exported
 * from the brand library when it is available; the shape is traced from the CRM frame at 1440.
 */
export function MbankLogo({ className, ...props }: React.ComponentProps<"svg">) {
  const gradient = useId()
  return (
    <svg viewBox="0 0 36 36" aria-hidden="true" className={cn("size-9 shrink-0", className)} {...props}>
      <defs>
        <linearGradient id={gradient} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" style={{ stopColor: "var(--brand-bank)" }} />
          <stop offset="1" style={{ stopColor: "var(--supportive-10)" }} />
        </linearGradient>
      </defs>
      <rect width="36" height="36" rx="7" fill={`url(#${gradient})`} />
      <path
        d="M11.5 25.5V11.5l5 5"
        fill="none"
        strokeWidth="4.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ stroke: "var(--primary-hover)" }}
      />
      <path
        d="M18 15.5l4.5-4v14"
        fill="none"
        strokeWidth="4.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ stroke: "var(--static-light)" }}
      />
    </svg>
  )
}

type SideMenuBrandProps = {
  /** Product name, one line: "MBANK CRM". */
  name: string
  /** Logo instead of the Mbank mark (another product). */
  logo?: React.ReactNode
  className?: string
}

/** Figma `logoCont` of `sideMenu`: logo 36 + product name 20/28 bold, one line, truncated. */
export function SideMenuBrand({ name, logo, className }: SideMenuBrandProps) {
  return (
    <span data-slot="side-menu-brand" className={cn("flex min-w-0 items-center gap-3", className)}>
      {logo ?? <MbankLogo />}
      <span className="truncate text-xl font-bold whitespace-nowrap text-soft-foreground">{name}</span>
    </span>
  )
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Button } from "@/registry/mbank/ui/button"
import { ChevronsLeftIcon } from "./crm-icons"
import { SideMenuSection } from "./SideMenuSection"
import type { RenderSideMenuLink, SideMenuSectionData } from "./side-menu-types"

type SideMenuProps = {
  /** Logo + product name (Figma `logoCont`, 76px). */
  brand: React.ReactNode
  sections: SideMenuSectionData[]
  /** Sections pinned to the bottom (Помощь: Настройки, База знаний, ...). */
  footerSections?: SideMenuSectionData[]
  /** Usually <SideMenuUser />. */
  user?: React.ReactNode
  activeId?: string
  renderLink?: RenderSideMenuLink
  collapsed?: boolean
  /** Shows the "<<" button in the logo row. */
  onToggleCollapsed?: () => void
  label?: string
  className?: string
}

/** Figma `sideMenu` (280px, background/onsurface/1): logo, menu groups, help group, user. */
export function SideMenu({
  brand,
  sections,
  footerSections = [],
  user,
  activeId,
  renderLink,
  collapsed = false,
  onToggleCollapsed,
  label = "Главное меню",
  className,
}: SideMenuProps) {
  const sectionProps = { activeId, collapsed, renderLink }
  return (
    <nav
      aria-label={label}
      data-slot="side-menu"
      data-collapsed={collapsed || undefined}
      className={cn("flex h-full min-h-0 flex-col bg-surface-1 text-foreground", className)}
    >
      <div className={cn("flex h-19 shrink-0 items-center justify-between gap-2 px-5", collapsed && "justify-center px-2")}>
        {!collapsed && brand}
        {onToggleCollapsed && (
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label={collapsed ? "Развернуть меню" : "Свернуть меню"}
            aria-pressed={collapsed}
            onClick={onToggleCollapsed}
            className="text-muted-foreground"
          >
            <ChevronsLeftIcon className={cn(collapsed && "rotate-180")} />
          </Button>
        )}
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto">
        {sections.map((section) => (
          <SideMenuSection key={section.id} section={section} {...sectionProps} />
        ))}
      </div>
      {(footerSections.length > 0 || user) && (
        <div className="shrink-0">
          <div className="mx-3 border-t border-border" />
          <div>
            {footerSections.map((section) => (
              <SideMenuSection key={section.id} section={section} {...sectionProps} />
            ))}
          </div>
          {user && <div className="px-3 pb-4">{user}</div>}
        </div>
      )}
    </nav>
  )
}

import type * as React from "react"

import { Avatar, AvatarFallback, AvatarImage } from "@/registry/mbank/ui/avatar"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/registry/mbank/ui/dropdown-menu"
import { MoreVerticalIcon } from "./crm-icons"

type SideMenuUserProps = {
  name: string
  role?: string
  avatarSrc?: string
  /** Two letters shown while the photo loads or when there is none. */
  initials: string
  /** DropdownMenuItem elements (Профиль, Выйти). Without them the "⋮" button is hidden. */
  children?: React.ReactNode
}

/** User card at the bottom of the Figma `sideMenu` (role above the short name, "⋮" menu). */
export function SideMenuUser({ name, role, avatarSrc, initials, children }: SideMenuUserProps) {
  return (
    <div data-slot="side-menu-user" className="flex h-11 items-center gap-3 rounded-md bg-surface-2 px-3">
      <Avatar size="xs" className="size-7">
        {avatarSrc && <AvatarImage src={avatarSrc} alt="" />}
        <AvatarFallback>{initials}</AvatarFallback>
      </Avatar>
      <div className="flex min-w-0 flex-1 flex-col">
        {role && <span className="truncate text-2xs text-muted-foreground">{role}</span>}
        <span className="truncate text-sm text-foreground">{name}</span>
      </div>
      {children && (
        <DropdownMenu>
          <DropdownMenuTrigger
            aria-label="Меню пользователя"
            className="inline-flex size-8 items-center justify-center rounded-sm text-muted-foreground outline-none hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/30"
          >
            <MoreVerticalIcon className="size-5" />
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" side="top">
            {children}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </div>
  )
}

import { useState } from "react"
import type * as React from "react"

import { Button } from "@/registry/mbank/ui/button"
import { Dialog, DialogContent, DialogTitle, DialogTrigger } from "@/registry/mbank/ui/dialog"
import { MenuIcon } from "./crm-icons"

type SideMenuSheetProps = {
  /** The same <SideMenu /> the desktop layout shows. */
  children: React.ReactNode
  label?: string
}

/**
 * Below 1024px the side menu moves into a left drawer opened by a menu button (put this in
 * TopHeader `leading`). Clicking a link inside closes it. Built on the kit Dialog: focus trap,
 * Esc, scroll lock come from Radix.
 */
export function SideMenuSheet({ children, label = "Главное меню" }: SideMenuSheetProps) {
  const [open, setOpen] = useState(false)
  const closeOnLink = (event: React.MouseEvent) => {
    if ((event.target as HTMLElement).closest("a")) setOpen(false)
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="ghost" size="icon-sm" aria-label={label} className="lg:hidden">
          <MenuIcon />
        </Button>
      </DialogTrigger>
      <DialogContent
        aria-describedby={undefined}
        onClick={closeOnLink}
        className="top-0 left-0 h-dvh max-h-dvh w-70 max-w-[85vw] translate-x-0 translate-y-0 gap-0 rounded-none bg-surface-1 p-0 data-[state=closed]:zoom-out-100 data-[state=open]:zoom-in-100 data-[state=closed]:slide-out-to-left data-[state=open]:slide-in-from-left"
      >
        <DialogTitle className="sr-only">{label}</DialogTitle>
        {children}
      </DialogContent>
    </Dialog>
  )
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"

type CrmLayoutProps = {
  /** <SideMenu />; shown from 1024px, below that put <SideMenuSheet> in the header. */
  sideMenu: React.ReactNode
  /** <TopHeader />, sticky. */
  header: React.ReactNode
  /** Banner above everything, e.g. <OfflineBanner />. */
  banner?: React.ReactNode
  /** Icon-only rail (72px) instead of 280px. */
  collapsed?: boolean
  children: React.ReactNode
  className?: string
}

/** Figma CRM frame 1440: sideMenu 280 + content (topHeader 68, Body on background/onsurface/1). */
export function CrmLayout({ sideMenu, header, banner, collapsed = false, children, className }: CrmLayoutProps) {
  return (
    <div
      data-slot="crm-layout"
      className={cn(
        "min-h-dvh bg-surface-1 text-foreground lg:grid",
        collapsed ? "lg:grid-cols-[72px_minmax(0,1fr)]" : "lg:grid-cols-[280px_minmax(0,1fr)]",
        className,
      )}
    >
      <aside className="sticky top-0 hidden h-dvh lg:block">{sideMenu}</aside>
      <div className="flex min-w-0 flex-col">
        {banner}
        {header}
        <main id="main" className="flex-1 p-4 sm:p-6">
          {children}
        </main>
      </div>
    </div>
  )
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"

type TopHeaderProps = {
  /** Page title (h1). Leave empty when the page shows breadcrumbs and its own h1. */
  title?: React.ReactNode
  /** "p" when the title is the section/product name and the page h1 is in the body (Figma: "Кредитный конвейер" + "Конвейер на 12 октября"). */
  titleAs?: "h1" | "p"
  /** <Breadcrumbs /> instead of the title (Figma `topHeader subheader`). */
  breadcrumbs?: React.ReactNode
  /** Back link/button before the title, e.g. an icon Button with ChevronLeftIcon. */
  back?: React.ReactNode
  /** Mobile menu trigger: <SideMenuSheet>. */
  leading?: React.ReactNode
  /** <HeaderSearch />, hidden below 768px. */
  search?: React.ReactNode
  /** Buttons such as "Экспорт", <HeaderIconButton>s. */
  actions?: React.ReactNode
  /** <UserMenu />. */
  user?: React.ReactNode
  className?: string
}

/** Figma `topHeader` (68px, background/surface/light, bottom divider): title left, tools right. */
export function TopHeader({ title, titleAs: Title = "h1", breadcrumbs, back, leading, search, actions, user, className }: TopHeaderProps) {
  return (
    <header
      data-slot="top-header"
      className={cn(
        "sticky top-0 z-(--z-sticky) flex h-17 shrink-0 items-center gap-3 border-b border-border bg-background px-4 sm:px-6 lg:px-10",
        className,
      )}
    >
      {leading}
      <div className="flex min-w-0 flex-1 items-center gap-3">
        {back}
        {title && <Title className="truncate text-lg font-bold text-foreground">{title}</Title>}
        {breadcrumbs}
      </div>
      <div className="flex shrink-0 items-center gap-2 md:gap-4">
        {search && <div className="hidden md:block">{search}</div>}
        {actions && <div className="flex items-center gap-2">{actions}</div>}
        {user}
      </div>
    </header>
  )
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"

export type BreadcrumbItem = { id: string; label: string; href?: string }

type BreadcrumbLinkProps = { item: BreadcrumbItem; className: string; children: React.ReactNode }

type BreadcrumbsProps = {
  items: BreadcrumbItem[]
  /** Router link for items with href (default: <a href>). The last item is the current page. */
  renderLink?: (props: BreadcrumbLinkProps) => React.ReactNode
  className?: string
}

const anchor = ({ item, ...props }: BreadcrumbLinkProps) => <a href={item.href} {...props} />

/**
 * Figma `topHeader subheader`: Кредиты / На андеррайтинге / CL-240118 (18/26, muted parents).
 * The current item never truncates; parents truncate first and hide below 768px.
 */
export function Breadcrumbs({ items, renderLink = anchor, className }: BreadcrumbsProps) {
  return (
    <nav aria-label="Хлебные крошки" data-slot="breadcrumbs" className={cn("min-w-0", className)}>
      <ol className="flex min-w-0 items-center text-lg">
        {items.map((item, index) => {
          const last = index === items.length - 1
          return (
            <li key={item.id} className={cn("flex items-center whitespace-nowrap", last ? "shrink-0" : "min-w-0 max-md:hidden")}>
              {last ? (
                <span aria-current="page" className="truncate font-medium text-foreground">
                  {item.label}
                </span>
              ) : item.href ? (
                renderLink({
                  item,
                  className: "truncate text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/30 rounded-xs",
                  children: item.label,
                })
              ) : (
                <span className="truncate text-muted-foreground">{item.label}</span>
              )}
              {!last && (
                <span aria-hidden="true" className="px-2 text-muted-foreground">
                  /
                </span>
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

import { useId } from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Input } from "@/registry/mbank/ui/input"
import { SearchIcon } from "./crm-icons"

type HeaderSearchProps = {
  /** Called on Enter with the trimmed query. */
  onSearch: (query: string) => void
  placeholder?: string
  label?: string
  defaultValue?: string
  className?: string
}

/** Figma `Search` in topHeader: input S (36px), 272px, search icon on the left. */
export function HeaderSearch({
  onSearch,
  placeholder = "Номер заявки, ИНН или ФИО",
  label = "Поиск",
  defaultValue,
  className,
}: HeaderSearchProps) {
  const id = useId()
  return (
    <form
      role="search"
      className={cn("relative w-68", className)}
      onSubmit={(event) => {
        event.preventDefault()
        const query = new FormData(event.currentTarget).get("q")
        onSearch(String(query ?? "").trim())
      }}
    >
      <label htmlFor={id} className="sr-only">
        {label}
      </label>
      <SearchIcon className="pointer-events-none absolute top-1/2 left-2.5 size-5 -translate-y-1/2 text-muted-foreground" />
      <Input id={id} name="q" type="search" size="sm" placeholder={placeholder} defaultValue={defaultValue} className="pl-9" />
    </form>
  )
}

import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Button } from "@/registry/mbank/ui/button"

type HeaderIconButtonProps = React.ComponentProps<typeof Button> & {
  /** Accessible name, e.g. "Уведомления". */
  label: string
  /** Red dot in the corner (Figma `Bell` + `indicator` 8px). */
  indicator?: boolean
}

/** Figma `iconCont` 36x36 on background/surface/soft with a 20px icon. */
export function HeaderIconButton({ label, indicator = false, className, children, ...props }: HeaderIconButtonProps) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      aria-label={indicator ? `${label}, есть новые` : label}
      className={cn("relative bg-muted text-foreground hover:bg-accent", className)}
      {...props}
    >
      {children}
      {indicator && (
        <span aria-hidden="true" className="absolute top-2 right-2 size-2 rounded-full bg-status-error ring-2 ring-muted" />
      )}
    </Button>
  )
}

import type * as React from "react"

import { Avatar, AvatarFallback, AvatarImage } from "@/registry/mbank/ui/avatar"
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from "@/registry/mbank/ui/dropdown-menu"
import { ChevronDownIcon } from "@/registry/mbank/ui/icons"

type UserMenuProps = {
  name: string
  role?: string
  avatarSrc?: string
  initials: string
  /** Green dot on the avatar (Figma `status` online). */
  online?: boolean
  /** DropdownMenuItem elements: Профиль, Сменить роль, Выйти. */
  children: React.ReactNode
}

/** Figma `avatarCont` in topHeader: soft pill, photo 36 (+ online dot) + name (14 bold) + role (11 muted) + chevron. */
export function UserMenu({ name, role, avatarSrc, initials, online = false, children }: UserMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        data-slot="user-menu"
        aria-label={`Профиль: ${name}${online ? ", в сети" : ""}`}
        className="flex h-9 items-center gap-2 rounded-md text-left outline-none hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/30 md:bg-muted md:pr-2"
      >
        <span className="relative shrink-0">
          <Avatar size="md" className="size-9 rounded-md">
            {avatarSrc && <AvatarImage src={avatarSrc} alt="" />}
            <AvatarFallback className="rounded-md bg-surface-3">{initials}</AvatarFallback>
          </Avatar>
          {online && (
            <span aria-hidden="true" className="absolute -bottom-0.5 left-0.5 size-2 rounded-full bg-status-success ring-2 ring-muted" />
          )}
        </span>
        <span className="hidden min-w-0 flex-col xl:flex">
          <span className="truncate text-sm font-bold text-foreground">{name}</span>
          {role && <span className="truncate text-2xs text-muted-foreground">{role}</span>}
        </span>
        <ChevronDownIcon className="hidden size-5 text-muted-foreground md:block" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">{children}</DropdownMenuContent>
    </DropdownMenu>
  )
}
